import unittest
from candidate import filter_by_prefix

class TestFilterByPrefix(unittest.TestCase):
    def test_filter_by_prefix_normal_case_with_matches(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde', 'array'], 'a'), ['abc', 'array'])

    def test_filter_by_prefix_normal_case_no_matches(self):
        self.assertEqual(filter_by_prefix(['bc', 'cd', 'de'], 'a'), [])

    def test_filter_by_prefix_empty_input_list(self):
        self.assertEqual(filter_by_prefix([], 'a'), [])

    def test_filter_by_prefix_empty_prefix(self):
        self.assertEqual(filter_by_prefix(['abc', 'def'], ''), ['abc', 'def'])

    def test_filter_by_prefix_none_strings_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(None, 'a')

